package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class ImportancePerformanceChecks {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("IPMA check "+checks);}
    private static void close(double a,double b,double tolerance){checks++;if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a-b)>tolerance*Math.max(1,Math.abs(b)))throw new AssertionError("IPMA "+a+" != "+b);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid IPMA accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();Random random=new Random(20261113);List<String> names=List.of("X1","X2","M1","M2","Y1","Y2","Unused");var blocks=List.of(new PlsSem.Block("X",new int[]{0,1},PlsSem.Mode.A),new PlsSem.Block("M",new int[]{2,3},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{4,5},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var modelOptions=new PlsSem.Options(3000,1e-10,PlsSem.Weighting.PATH);double[][] data=new double[180][7];
        for(int i=0;i<data.length;i++){double x=random.nextGaussian(),m=.65*x+.8*random.nextGaussian(),y=.25*x+.55*m+.8*random.nextGaussian();for(int j=0;j<6;j++)data[i][j]=Math.max(1,Math.min(7,4+new double[]{x,x,m,m,y,y}[j]+.3*random.nextGaussian()));data[i][6]=42;}
        for(var depth:ImportancePerformance.Depth.values())for(var units:ImportancePerformance.Units.values())for(int variant=0;variant<5;variant++){
            double[][] observations=Matrices.copy(data);List<ImportancePerformance.Range> ranges=new ArrayList<>();if(variant>0)for(int j=0;j<6;j++)ranges.add(new ImportancePerformance.Range(j,variant==3&&j==1?2:1,variant==3&&j==1?14:7,variant==2&&j==1));if(variant==2)for(double[] row:observations)row[1]=8-row[1];if(variant==3)for(double[] row:observations)row[1]*=2;if(variant==4)for(double[] row:observations){row[4]=8-row[4];row[5]=8-row[5];}var options=new ImportancePerformance.Options(2,depth,units,ranges);var fit=ImportancePerformance.fit(observations,names,blocks,edges,modelOptions,options);check(fit.constructs().size()==2&&fit.indicators().size()==4);check(fit.resolvedRanges().size()==6);check(Double.isNaN(fit.indicatorPerformance()[6]));for(int j=0;j<3;j++){close(Arrays.stream(fit.rescaledWeights()[j]).sum(),1,1e-14);check(Arrays.stream(fit.rescaledWeights()[j]).allMatch(v->v>=0));check(fit.constructPerformance()[j]>=0&&fit.constructPerformance()[j]<=100);}
            close(fit.totalEffects()[0][2],fit.paths()[0][2]+fit.paths()[0][1]*fit.paths()[1][2],1e-13);close(fit.totalEffects()[1][2],fit.paths()[1][2],1e-13);if(units==ImportancePerformance.Units.ORIGINAL_UNITS){double[][] raw=fit.rawConstructScores();var regression=OlsRegression.fit(Arrays.stream(raw).map(row->new double[]{row[0],row[1]}).toArray(double[][]::new),Arrays.stream(raw).mapToDouble(row->row[2]).toArray());close(regression.coefficients()[1],fit.paths()[0][2],1e-10);close(regression.coefficients()[2],fit.paths()[1][2],1e-10);}
            JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(observations));test.add("names",gson.toJsonTree(names));test.add("blocks",gson.toJsonTree(blocks));test.add("edges",gson.toJsonTree(edges));test.add("modelOptions",gson.toJsonTree(modelOptions));test.add("options",gson.toJsonTree(options));test.add("result",gson.toJsonTree(fit));cases.add(test);
        }
        var chain=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(1,2));for(var depth:ImportancePerformance.Depth.values()){var options=new ImportancePerformance.Options(2,depth,ImportancePerformance.Units.ORIGINAL_UNITS,List.of());var result=ImportancePerformance.fit(data,names,blocks,chain,modelOptions,options);check(result.constructs().size()==(depth==ImportancePerformance.Depth.DIRECT_PREDECESSORS?1:2));JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(data));test.add("names",gson.toJsonTree(names));test.add("blocks",gson.toJsonTree(blocks));test.add("edges",gson.toJsonTree(chain));test.add("modelOptions",gson.toJsonTree(modelOptions));test.add("options",gson.toJsonTree(options));test.add("result",gson.toJsonTree(result));cases.add(test);}
        reject(()->ImportancePerformance.fit(data,names,blocks,edges,modelOptions,ImportancePerformance.Options.defaults(0)));reject(()->ImportancePerformance.fit(data,names,blocks,edges,modelOptions,new ImportancePerformance.Options(2,ImportancePerformance.Depth.ALL_PREDECESSORS,ImportancePerformance.Units.ORIGINAL_UNITS,List.of(new ImportancePerformance.Range(0,2,3,false)))));reject(()->new ImportancePerformance.Range(0,1,1,false));reject(()->ImportancePerformance.fit(data,names,blocks,edges,modelOptions,new ImportancePerformance.Options(2,ImportancePerformance.Depth.ALL_PREDECESSORS,ImportancePerformance.Units.ORIGINAL_UNITS,List.of(new ImportancePerformance.Range(6,1,50,false)))));
        double[][] mixed=Matrices.copy(data);for(double[] row:mixed)row[1]=8-row[1];reject(()->ImportancePerformance.fit(mixed,names,blocks,edges,modelOptions,ImportancePerformance.Options.defaults(2)));reject(()->ImportancePerformance.fit(data,names,blocks,edges,new PlsSem.Options(1,1e-20,PlsSem.Weighting.PATH),ImportancePerformance.Options.defaults(2)));
        Thread.currentThread().interrupt();try{ImportancePerformance.fit(data,names,blocks,edges,modelOptions,ImportancePerformance.Options.defaults(2));throw new AssertionError("IPMA ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"ipma_cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
